const PORTALE_VISORE = "<style>" +
  "#gl-v{position:fixed;inset:0;z-index:9999;background:#000;display:none;flex-direction:column}" +
  "#gl-v.on{display:flex}" +
  "#gl-v .bar{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;color:#fff;font:600 .95rem system-ui,sans-serif;background:rgba(0,0,0,.6)}" +
  "#gl-v .bar span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}" +
  "#gl-v button{background:none;border:0;color:#fff;font-size:1.6rem;line-height:1;padding:6px 10px;cursor:pointer}" +
  "#gl-v .trk{flex:1;touch-action:pan-x;display:flex;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;scrollbar-width:none}" +
  "#gl-v .trk::-webkit-scrollbar{display:none}" +
  "#gl-v .sl{flex:0 0 100%;width:100%;height:100%;scroll-snap-align:center;scroll-snap-stop:always;display:flex;align-items:center;justify-content:center;overflow:hidden}" +
  "#gl-v .sl img{max-width:100%;max-height:100%;object-fit:contain;transform-origin:center center;will-change:transform;user-select:none;-webkit-user-select:none}" +
  "#gl-v .fr{position:absolute;top:50%;transform:translateY(-50%);font-size:2.4rem;background:rgba(0,0,0,.35);border-radius:50%;width:48px;height:48px;padding:0}" +
  "#gl-v .fr.sx{left:8px}#gl-v .fr.dx{right:8px}" +
  "@media (hover:none){#gl-v .fr{display:none}}" +
  "</style>" +
  "<div id=\"gl-v\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Foto a tutto schermo\">" +
  "<div class=\"bar\"><span id=\"gl-v-t\"></span><button type=\"button\" id=\"gl-v-x\" aria-label=\"Chiudi\">&times;</button></div>" +
  "<div class=\"trk\" id=\"gl-v-k\"></div>" +
  "<button type=\"button\" class=\"fr sx\" id=\"gl-v-p\" aria-label=\"Foto precedente\">&lsaquo;</button>" +
  "<button type=\"button\" class=\"fr dx\" id=\"gl-v-n\" aria-label=\"Foto successiva\">&rsaquo;</button></div>" +
  "<script>" + "(function(){try{\nvar V=document.getElementById('gl-v'),K=document.getElementById('gl-v-k'),T=document.getElementById('gl-v-t');\nvar lista=[],cur=0,aperto=false,raf=0;\nvar z={s:1,x:0,y:0,img:null};\nfunction nota(a){var l=a.getAttribute('aria-label')||'';return l.replace(/^Foto delle /,'ore ');}\nfunction applica(){if(!z.img)return;z.img.style.transform='translate('+z.x+'px,'+z.y+'px) scale('+z.s+')';K.style.overflowX=z.s>1.01?'hidden':'auto';}\nfunction limita(){if(!z.img)return;var r=z.img.parentNode.getBoundingClientRect();var w=z.img.offsetWidth*z.s,h=z.img.offsetHeight*z.s;var mx=Math.max(0,(w-r.width)/2),my=Math.max(0,(h-r.height)/2);z.x=Math.max(-mx,Math.min(mx,z.x));z.y=Math.max(-my,Math.min(my,z.y));}\nfunction azzera(){if(z.img){z.img.style.transition='';z.img.style.transform='';}z={s:1,x:0,y:0,img:null};K.style.overflowX='auto';}\nfunction zoomA(s,cx,cy){var im=K.children[cur]&&K.children[cur].querySelector('img');if(!im)return;if(z.img!==im){azzera();z.img=im;}var r=im.parentNode.getBoundingClientRect();var px=cx-(r.left+r.width/2),py=cy-(r.top+r.height/2);var k=s/z.s;z.x=px-(px-z.x)*k;z.y=py-(py-z.y)*k;z.s=s;if(z.s<=1.01){z.s=1;z.x=0;z.y=0;}limita();applica();}\nfunction carica(i){for(var j=i-2;j<=i+2;j++){var s=K.children[j];if(s&&!s.firstChild){var im=document.createElement('img');im.alt='';im.decoding='async';im.draggable=false;im.src=lista[j].src;s.appendChild(im);}}}\nfunction titolo(){T.textContent=(cur+1)+' / '+lista.length+(lista[cur].nota?' \u00b7 '+lista[cur].nota:'');}\nfunction vai(i,liscio){azzera();i=Math.max(0,Math.min(lista.length-1,i));cur=i;carica(i);titolo();K.scrollTo({left:i*K.clientWidth,behavior:liscio?'smooth':'auto'});}\nfunction apri(gruppo,i){lista=gruppo;K.innerHTML='';for(var j=0;j<lista.length;j++){var d=document.createElement('div');d.className='sl';K.appendChild(d);}\nV.classList.add('on');document.documentElement.style.overflow='hidden';if(!aperto){aperto=true;try{history.pushState({glv:1},'')}catch(e){}}vai(i,false);}\nfunction chiudi(daStoria){if(!aperto)return;aperto=false;azzera();V.classList.remove('on');K.innerHTML='';document.documentElement.style.overflow='';if(!daStoria){try{history.back()}catch(e){}}}\nK.addEventListener('scroll',function(){if(raf)return;raf=requestAnimationFrame(function(){raf=0;var i=Math.round(K.scrollLeft/Math.max(1,K.clientWidth));if(i!==cur&&lista[i]){if(z.img)azzera();cur=i;carica(i);titolo();}});},{passive:true});\n/* gesti: due dita = ingrandisci; doppio tocco = 2,5x / torna; un dito con foto ingrandita = sposta */\nvar g=null,ultimoTap=0;\nfunction dist(t){var dx=t[0].clientX-t[1].clientX,dy=t[0].clientY-t[1].clientY;return Math.sqrt(dx*dx+dy*dy);}\nK.addEventListener('touchstart',function(e){var t=e.touches;\n if(t.length===2){e.preventDefault();var im=K.children[cur]&&K.children[cur].querySelector('img');if(im&&z.img!==im){azzera();z.img=im;}g={tipo:'pinch',d0:dist(t),s0:z.s,cx:(t[0].clientX+t[1].clientX)/2,cy:(t[0].clientY+t[1].clientY)/2};}\n else if(t.length===1){var ora=Date.now();if(ora-ultimoTap<300){e.preventDefault();zoomA(z.s>1.01?1:2.5,t[0].clientX,t[0].clientY);ultimoTap=0;g=null;return;}ultimoTap=ora;\n  if(z.s>1.01){g={tipo:'pan',x0:t[0].clientX,y0:t[0].clientY,zx:z.x,zy:z.y};}else g=null;}\n},{passive:false});\nK.addEventListener('touchmove',function(e){if(!g)return;var t=e.touches;\n if(g.tipo==='pinch'&&t.length===2){e.preventDefault();var s=Math.max(1,Math.min(6,g.s0*dist(t)/g.d0));zoomA(s,g.cx,g.cy);}\n else if(g.tipo==='pan'&&t.length===1){e.preventDefault();z.x=g.zx+(t[0].clientX-g.x0);z.y=g.zy+(t[0].clientY-g.y0);limita();applica();}\n},{passive:false});\nK.addEventListener('touchend',function(e){if(e.touches.length===0)g=null;else if(g&&g.tipo==='pinch'&&e.touches.length===1&&z.s>1.01){g={tipo:'pan',x0:e.touches[0].clientX,y0:e.touches[0].clientY,zx:z.x,zy:z.y};}},{passive:true});\n/* computer: rotellina e doppio clic */\nK.addEventListener('wheel',function(e){if(!e.ctrlKey&&Math.abs(e.deltaY)<Math.abs(e.deltaX))return;e.preventDefault();zoomA(Math.max(1,Math.min(6,z.s*(e.deltaY<0?1.2:1/1.2))),e.clientX,e.clientY);},{passive:false});\nK.addEventListener('dblclick',function(e){zoomA(z.s>1.01?1:2.5,e.clientX,e.clientY);});\nvar md=null;K.addEventListener('mousedown',function(e){if(z.s>1.01){md={x0:e.clientX,y0:e.clientY,zx:z.x,zy:z.y};e.preventDefault();}});\nwindow.addEventListener('mousemove',function(e){if(!md)return;z.x=md.zx+(e.clientX-md.x0);z.y=md.zy+(e.clientY-md.y0);limita();applica();});\nwindow.addEventListener('mouseup',function(){md=null;});\nwindow.addEventListener('resize',function(){if(aperto)vai(cur,false);});\nwindow.addEventListener('popstate',function(){if(aperto)chiudi(true);});\ndocument.getElementById('gl-v-x').addEventListener('click',function(){chiudi(false);});\ndocument.getElementById('gl-v-p').addEventListener('click',function(){vai(cur-1,true);});\ndocument.getElementById('gl-v-n').addEventListener('click',function(){vai(cur+1,true);});\ndocument.addEventListener('keydown',function(e){if(!aperto)return;if(e.key==='Escape')chiudi(false);else if(e.key==='ArrowLeft')vai(cur-1,true);else if(e.key==='ArrowRight')vai(cur+1,true);});\ndocument.addEventListener('click',function(e){if(aperto)return;var a=e.target&&e.target.closest?e.target.closest('a'):null;if(!a||!a.querySelector('img'))return;\nvar cont=a.closest('.pann')||a.closest('main')||document.body;var aa=cont.querySelectorAll('a');var gg=[],idx=0;\nfor(var j=0;j<aa.length;j++){var im=aa[j].querySelector('img');if(!im)continue;if(aa[j]===a)idx=gg.length;gg.push({src:aa[j].getAttribute('href')||im.getAttribute('src'),nota:nota(aa[j])});}\nif(!gg.length)return;e.preventDefault();apri(gg,idx);},true);\n}catch(x){}})();\n" + "</script>";

async function portaleRoute(request, env, prefisso) {
  const metodo = request.method;
  if (metodo !== "GET" && metodo !== "HEAD") {
    return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
  }
  const inUrl = new URL(request.url);
  const base = prefisso; // "" sul dominio dedicato, "/portale" su workers.dev
  let sotto = inUrl.pathname.slice(prefisso.length) || "/";

  if (sotto === "/manifest.webmanifest") {
    const manifest = {
      id: base + "/",
      name: "Il Giornale Lavori",
      short_name: "Giornale Lavori",
      description: "I cantieri della tua impresa: giornale, rapportini, DDT, foto e documenti.",
      lang: "it",
      start_url: base + "/",
      scope: base + "/",
      display: "standalone",
      orientation: "portrait",
      background_color: "#FFFFFF",
      theme_color: PORTALE_COLORE,
      icons: [
        { src: base + "/icona-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
        { src: base + "/icona-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
        { src: base + "/icona-maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
        { src: base + "/icona-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
      ]
    };
    return new Response(JSON.stringify(manifest), {
      status: 200,
      headers: { "Content-Type": "application/manifest+json; charset=UTF-8", "Cache-Control": "public, max-age=3600" }
    });
  }

  if (sotto === "/sw.js") {
    return new Response(PORTALE_SW, {
      status: 200,
      headers: { "Content-Type": "application/javascript; charset=UTF-8", "Cache-Control": "no-cache" }
    });
  }

  if (PORTALE_ICONE.has(sotto)) {
    const r = await env.ASSETS.fetch(new Request(inUrl.origin + "/portale" + sotto));
    if (!r.ok) return new Response("Not Found", { status: 404 });
    const h = new Headers(r.headers);
    h.set("Cache-Control", "public, max-age=86400");
    return new Response(metodo === "HEAD" ? null : r.body, { status: 200, headers: h });
  }

  if (sotto === "/robots.txt") {
    return new Response("User-agent: *\nDisallow: /\n", { status: 200, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }

  if (sotto !== "/" && sotto !== "/index.html") {
    return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }

  const tGrezzo = inUrl.searchParams.get("t");
  if (tGrezzo === null) {
    return new Response(metodo === "HEAD" ? null : portaleIngresso(base, ""), { status: 200, headers: portaleHtmlHeaders() });
  }
  const m = String(tGrezzo).match(/[0-9a-fA-F]{64}/);
  if (!m) {
    return new Response(portaleIngresso(base, "Il collegamento non è completo. Incollalo di nuovo per intero."), { status: 200, headers: portaleHtmlHeaders() });
  }
  const token = m[0].toLowerCase();
  const commessa = (inUrl.searchParams.get("c") || "").slice(0, 64);

  if (!env.SUPABASE_SERVICE_KEY) {
    return new Response("Servizio non configurato.", { status: 503, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25000);
  let html;
  try {
    const r = await fetch(supabaseUrl + "/rest/v1/rpc/dashboard_html", {
      method: "POST",
      headers: {
        "apikey": env.SUPABASE_SERVICE_KEY,
        "Authorization": "Bearer " + env.SUPABASE_SERVICE_KEY,
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify({ p_token: token, p_commessa: commessa }),
      signal: ctrl.signal
    });
    if (!r.ok) throw new Error("rpc " + r.status);
    html = await r.json();
    if (typeof html !== "string") throw new Error("risposta non testuale");
  } catch (e) {
    clearTimeout(timer);
    return new Response(portaleIngresso(base, "Il servizio non risponde in questo momento. Riprova tra qualche minuto."), {
      status: 503, headers: portaleHtmlHeaders({ "Retry-After": "60" })
    });
  }
  clearTimeout(timer);

  // Pagina valida = contiene i collegamenti con il gettone (le pagine di errore non lo riportano mai).
  const valida = html.indexOf("?t=" + token) !== -1;
  let script = valida
    ? "<script>(function(){try{localStorage.setItem('gl_portale_t','" + token + "')}catch(e){}" + portaleScriptSw(base) + "})();</script>"
    : "<script>(function(){try{if(localStorage.getItem('gl_portale_t')==='" + token + "')localStorage.removeItem('gl_portale_t')}catch(e){}})();</script>";
  html = html.indexOf("</head>") !== -1 ? html.replace("</head>", portaleTesta(base) + "</head>") : html;
  if (valida && html.indexOf("<img") !== -1) script = PORTALE_VISORE + script;
  html = html.lastIndexOf("</body>") !== -1
    ? html.slice(0, html.lastIndexOf("</body>")) + script + html.slice(html.lastIndexOf("</body>"))
    : html + script;
  return new Response(metodo === "HEAD" ? null : html, { status: 200, headers: portaleHtmlHeaders() });
}
